cards.example:
apiVersion: apps/v1
kind: Deployment
metadata: { name: api }
spec:
  replicas: 3
  selector: { matchLabels: { app: api } }
  template:
    metadata: { labels: { app: api } }
    spec:
      containers:
        - name: api
          image: ghcr.io/org/api:1.4.2
          resources:
            requests: { cpu: 100m, memory: 128Mi }
            limits:   { cpu: 500m, memory: 512Mi }

envFrom:
  - configMapRef: { name: api-config }
  - secretRef:    { name: api-secrets }

kubectl create secret generic api-secrets --from-literal=DB_PASSWORD='...'

resources:
  requests: { cpu: 200m, memory: 256Mi }
  limits:   { cpu: '1', memory: 512Mi }

kubectl top pods    # реальное потребление

readinessProbe:
  httpGet: { path: /ready, port: 8000 }
  periodSeconds: 5
livenessProbe:
  httpGet: { path: /health, port: 8000 }
  failureThreshold: 3
startupProbe:
  httpGet: { path: /health, port: 8000 }
  failureThreshold: 30
